module med21 (
  input clk, input rst_n, input [7:0] x, output reg [15:0] y
);
  reg [7:0] window [0:20];
  reg [7:0] tmp;
  integer i, j, k;
  always @(posedge clk) begin
    if (!rst_n) begin
      for (i = 0; i < 21; i = i + 1) window[i] <= 8'd0;
      y <= 16'd0;
    end else begin
      window[0] <= x;
      for (i = 1; i < 21; i = i + 1) window[i] <= window[i-1];
      for (i = 0; i < 20; i = i + 1)
        for (j = i + 1; j < 21; j = j + 1)
          if (window[i] > window[j]) begin tmp <= window[i]; window[i] <= window[j]; window[j] <= tmp; end
      y <= {8'd0, window[10]};
    end
  end
endmodule

